package io.github.jesterportfolio.hearth.survival.platform;

import java.util.*;import java.util.concurrent.*;import java.nio.file.*;
import org.bukkit.*;
import io.github.jesterportfolio.hearth.economy.PlatformStore;
import io.github.jesterportfolio.hearth.economy.PlatformStore.Reset;
import io.github.jesterportfolio.hearth.survival.*;

/** 새 월드를 준비한 뒤 논리 역할을 교체한다. 원본 월드·이전 세대를 삭제하지 않는다. */
public final class ResourceGenerations {
    private final PlatformRuntime p;private final Map<SurvivalWorld,Reset> active=new EnumMap<>(SurvivalWorld.class);
    private final Map<UUID,Reset> pending=new LinkedHashMap<>();private final Set<SurvivalWorld> blocked=EnumSet.noneOf(SurvivalWorld.class);
    private final Map<UUID,Chunk> candidateTickets=new HashMap<>();
    private boolean working;private long deadline;
    public ResourceGenerations(PlatformRuntime p){this.p=p;}
    public boolean allowed(World world){var role=p.rpg.runtime.worlds().role(world);return role==null||!blocked.contains(role);}
    public boolean busy(){return working;}public List<Reset> pending(){return List.copyOf(pending.values());}public Map<SurvivalWorld,Reset> active(){return Map.copyOf(active);}
    public CompletionStage<Void> open(){return p.store.resets().thenComposeAsync(rows->{CompletionStage<Void> chain=CompletableFuture.completedFuture(null);for(var row:rows){var role=SurvivalWorld.id(row.role());if(row.phase().equals("ACTIVE")){chain=chain.thenComposeAsync(v->load(row,true).thenComposeAsync(at->install(row,at,false),p.owner),p.owner);}else if(Set.of("PREPARING","READY").contains(row.phase())){pending.put(row.request(),row);blocked.add(role);}}return chain;},p.owner);}
    public CompletionStage<Void> reset(SurvivalWorld role,long seed){
        if(!p.settings().resourceReset()||role==SurvivalWorld.RESIDENCE||working||blocked.contains(role)||p.maintenance())return CompletableFuture.failedFuture(new IllegalStateException("RESET_DISABLED_OR_BUSY"));
        World old=Objects.requireNonNull(p.rpg.runtime.worlds().worlds().get(role));long generation=Optional.ofNullable(active.get(role)).map(Reset::generation).orElse(0L);String terrain=old.getWorldType()==WorldType.FLAT?"FLAT":"NORMAL";
        working=true;blocked.add(role);deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(p.settings().resetTimeout());long start=System.nanoTime();UUID request=UUID.randomUUID();
        return track(p.store.reserve(request,role.id(),old.getUID(),generation,seed,terrain).thenComposeAsync(row->{pending.put(row.request(),row);return load(row,false).thenComposeAsync(at->{guard();at.getWorld().save(true);return p.store.prepared(row,at.getWorld().getUID(),at.getX(),at.getY(),at.getZ()).thenComposeAsync(prepared->{pending.put(prepared.request(),prepared);return evacuate(prepared,at);},p.owner);},p.owner);},p.owner),start);
    }
    public CompletionStage<List<Reset>> inspect(){return p.store.resets().thenApplyAsync(rows->{for(var row:rows)if(Set.of("PREPARING","READY").contains(row.phase())){pending.put(row.request(),row);blocked.add(SurvivalWorld.id(row.role()));}return rows;},p.owner);}
    public CompletionStage<Void> resume(UUID request){if(working)return CompletableFuture.failedFuture(new IllegalStateException("RESET_BUSY"));working=true;deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(p.settings().resetTimeout());long start=System.nanoTime();return track(p.store.resets().thenComposeAsync(rows->{var row=rows.stream().filter(r->r.request().equals(request)).findFirst().orElseThrow();if(!Set.of("READY","ACTIVE").contains(row.phase()))throw new IllegalStateException("RESET_NOT_PREPARED");blocked.add(SurvivalWorld.id(row.role()));return load(row,true).thenComposeAsync(at->row.phase().equals("ACTIVE")?install(row,at,false):evacuate(row,at),p.owner);},p.owner),start);}

    public CompletionStage<Void> abort(UUID request){var row=Objects.requireNonNull(pending.get(request));var role=SurvivalWorld.id(row.role());var current=p.rpg.runtime.worlds().worlds().get(role);if(working||!current.getUID().equals(row.oldWorld()))return CompletableFuture.failedFuture(new IllegalStateException("RESET_ABORT_REQUIRES_ORIGINAL_ROLE"));return p.store.abort(request).thenRunAsync(()->{pending.remove(request);blocked.remove(role);var ticket=candidateTickets.values().stream().filter(chunk->chunk.getWorld().getKey().toString().equals(row.key())).findFirst();ticket.ifPresent(chunk->{chunk.removePluginChunkTicket(p.plugin);candidateTickets.remove(chunk.getWorld().getUID());if(chunk.getWorld().getPlayers().isEmpty())Bukkit.unloadWorld(chunk.getWorld(),true);});},p.owner);}
    private CompletionStage<Void> track(CompletionStage<Void> work,long start){return work.toCompletableFuture().orTimeout(p.settings().resetTimeout(),TimeUnit.SECONDS).whenCompleteAsync((v,error)->{working=false;p.metrics.record("reset",System.nanoTime()-start,error!=null);if(error!=null)p.plugin.getLogger().warning("HEARTH_RESOURCE_RESET_HOLD pending="+pending.keySet());},p.owner);}
    private void guard(){if(!working||System.nanoTime()>deadline)throw new IllegalStateException("RESET_TIMEOUT_HOLD");}
    private CompletionStage<Location> load(Reset row,boolean existing){try{
        var key=Objects.requireNonNull(NamespacedKey.fromString(row.key()));if(!key.getNamespace().equals("hearth_resource")||!key.getKey().equals("r_"+row.role()+"_"+row.request().toString().replace("-","")))throw new IllegalStateException("RESET_KEY");
        Path level=Bukkit.getServer().getLevelDirectory().toRealPath(),path=level.resolve("dimensions").resolve(key.getNamespace()).resolve(key.getKey());for(Path parent=path;parent!=null&&!parent.equals(level);parent=parent.getParent())if(Files.isSymbolicLink(parent))throw new IllegalStateException("RESET_PATH");
        World world=Bukkit.getWorld(key);if(existing){if(row.world()==null||!path.equals(path.toRealPath())||!SurvivalWorlds.metadataUuid(path.resolve("data/paper/metadata.dat")).equals(row.world()))throw new IllegalStateException("RESET_STORED_IDENTITY");}else if(world!=null||Files.exists(path,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("RESET_UNKNOWN_CANDIDATE");
        var env=switch(SurvivalWorld.id(row.role())){case NETHER->World.Environment.NETHER;case END->World.Environment.THE_END;default->World.Environment.NORMAL;};
        if(world==null)world=Objects.requireNonNull(Bukkit.createWorld(WorldCreator.ofKey(key).environment(env).type(WorldType.valueOf(row.terrain())).seed(row.seed())));if(world.getEnvironment()!=env||world.getSeed()!=row.seed()||existing&&!world.getUID().equals(row.world()))throw new IllegalStateException("RESET_IDENTITY");
        var w=world;Location hint=existing?new Location(w,row.x(),row.y(),row.z()):w.getSpawnLocation();if(existing&&!w.isChunkGenerated(hint.getBlockX()>>4,hint.getBlockZ()>>4))throw new IllegalStateException("RESET_ENTRY_MISSING");
        return w.getChunkAtAsync(hint.getBlockX()>>4,hint.getBlockZ()>>4,!existing).thenApplyAsync(chunk->{if(chunk==null)throw new IllegalStateException("RESET_CHUNK");chunk.addPluginChunkTicket(p.plugin);candidateTickets.put(w.getUID(),chunk);var at=existing?hint:SurvivalWorlds.findSafe(w,hint);if(!SurvivalWorlds.safe(at))throw new IllegalStateException("RESET_ENTRY_UNSAFE");return at;},p.owner);
    }catch(Exception e){return CompletableFuture.failedFuture(e);}}
    private CompletionStage<Void> evacuate(Reset row,Location at){guard();var old=Bukkit.getWorld(row.oldWorld());var moves=new ArrayList<CompletableFuture<?>>();if(old!=null)for(var player:List.copyOf(old.getPlayers())){if(!p.rpg.runtime.current(player)||!p.rpg.runtime.economy().free(player))throw new IllegalStateException("RESET_PLAYER_BUSY");moves.add(p.rpg.runtime.evacuateResource(player).thenAccept(ok->{if(!ok)throw new IllegalStateException("RESET_EVACUATION_FAILED");}).toCompletableFuture());}return CompletableFuture.allOf(moves.toArray(CompletableFuture[]::new)).thenComposeAsync(v->{guard();if(old!=null&&!old.getPlayers().isEmpty())throw new IllegalStateException("RESET_OCCUPIED");return install(row,at,true);},p.owner);}
    private CompletionStage<Void> install(Reset row,Location at,boolean commit){boolean controlled=working;if(controlled)guard();var role=SurvivalWorld.id(row.role());var old=p.rpg.runtime.worlds().worlds().get(role);if(old!=null&&!old.getPlayers().isEmpty())return CompletableFuture.failedFuture(new IllegalStateException("RESET_OCCUPIED"));p.rpg.runtime.housing().protection.resource(at.getWorld(),at);p.rpg.runtime.worlds().replaceResource(role,at.getWorld(),at);candidateTickets.remove(at.getWorld().getUID());var retired=new HashSet<World>();if(old!=null)retired.add(old);var previous=Bukkit.getWorld(row.oldWorld());if(previous!=null)retired.add(previous);retired.remove(at.getWorld());for(var source:retired){if(!source.getPlayers().isEmpty())return CompletableFuture.failedFuture(new IllegalStateException("RESET_OLD_OCCUPIED"));source.save(true);if(!Bukkit.unloadWorld(source,true))return CompletableFuture.failedFuture(new IllegalStateException("RESET_OLD_UNLOAD_FAILED"));}
        return (commit?p.store.activate(row):CompletableFuture.<Void>completedFuture(null)).thenComposeAsync(v->{if(controlled)guard();return p.rpg.reprojectWorlds();},p.owner).thenRunAsync(()->{if(controlled)guard();active.put(role,new Reset(row.request(),row.role(),row.generation(),row.oldWorld(),row.key(),row.seed(),row.terrain(),row.world(),row.x(),row.y(),row.z(),"ACTIVE"));pending.remove(row.request());if(pending.values().stream().noneMatch(r->r.role().equals(role.id())))blocked.remove(role);p.rpg.runtime.admission().activate();},p.owner);
    }
    public void close(){for(var chunk:candidateTickets.values())chunk.removePluginChunkTicket(p.plugin);candidateTickets.clear();}

}
